from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class AdditionalInfo(SchemaObject):
    descriptive_name = SchemaField(name='descriptiveName', optional=True)
    mrbts_config_type = SchemaField(name='mrbtsConfigType', optional=True)
    region = SchemaField(name='region', optional=True)
    subregion = SchemaField(name='subregion', optional=True)
    group_name = SchemaField(name='groupName', optional=True)
    assignee = SchemaField(name='assignee', optional=True)
    integration_info = SchemaField(name='integrationInfo', optional=True)
    target_param_info = SchemaField(name='targetParamInfo', optional=True)

    def __init__(self, descriptive_name, mrbts_config_type, region, subregion, group_name, assignee, integration_info,
                 target_param_info):
        self.descriptive_name = descriptive_name
        self.mrbts_config_type = mrbts_config_type
        self.region = region
        self.subregion = subregion
        self.group_name = group_name
        self.assignee = assignee
        self.integration_info = integration_info
        self.target_param_info = target_param_info
        super(AdditionalInfo, self).__init__()


class CommonIPAddress(SchemaObject):
    ipv4 = SchemaField(name='v4', not_null=False)
    ipv6 = SchemaField(name='v6', not_null=False)

    def __init__(self, ipv4, ipv6):
        self.ipv4 = ipv4
        self.ipv6 = ipv6

        super(CommonIPAddress, self).__init__()


class IPAddresses(SchemaObject):
    cu_f1_c_ip_address = SchemaField(name="cuF1CIpAddress")
    m_plane_ip_address = SchemaField(name="mPlaneIpAddress", klass=CommonIPAddress, not_null=False)
    f1_c_ip_address = SchemaField(name="f1CIpAddress", klass=CommonIPAddress, not_null=False)
    f1_u_ip_address = SchemaField(name="f1UIpAddresses", many=True, klass=CommonIPAddress, not_null=False)

    def __init__(self, cu_f1_c_ip_address, m_plane_ip_address, f1_c_ip_address, f1_u_ip_address):
        self.m_plane_ip_address = m_plane_ip_address
        self.f1_c_ip_address = f1_c_ip_address
        self.f1_u_ip_address = f1_u_ip_address
        self.cu_f1_c_ip_address = cu_f1_c_ip_address

        super(IPAddresses, self).__init__()


# TODO: IpAddresses field should validate its content once ASM REST API changes will be done
class VDUStateData(SchemaObject):
    id = SchemaField(name="id", optional=True)
    name = SchemaField(name="name", optional=True)
    cu_name = SchemaField(name="cuName", optional=True)
    time_zone = SchemaField(name="timeZone")
    software_version = SchemaField(name="softwareVersion")
    mcc = SchemaField(name="mcc", optional=True)
    mnc = SchemaField(name="mnc", optional=True)
    mnc_length = SchemaField(name="mncLength", optional=True)
    operational_state = SchemaField(name="operationalState")
    f1_c_link_status_du = SchemaField(name="f1CLinkStatusDU")
    ip_addresses = SchemaField(name="ipAddresses", klass=IPAddresses)
    number_of_alarms = SchemaField(name="numberOfAlarms")
    mrbts_id = SchemaField(name="mrbtsId", optional=True)
    nrbts_id = SchemaField(name="nrbtsId")
    nr_du_id = SchemaField(name="nrDuId")
    additional_info = SchemaField(name='additionalInfo', klass=AdditionalInfo)
    is_vdu_start_up = SchemaField(name="isVduStartUp", not_null=True)

    def __init__(self, id, name, cu_name, time_zone, software_version, mcc, mnc, mnc_length, operational_state,
                 f1_c_link_status_du, number_of_alarms, ip_addresses, mrbts_id, nrbts_id, nr_du_id, is_vdu_start_up,
                 additional_info):
        self.id = id
        self.name = name
        self.cu_name = cu_name
        self.time_zone = time_zone
        self.software_version = software_version
        self.mcc = mcc
        self.mnc = mnc
        self.mnc_length = mnc_length
        self.operational_state = operational_state
        self.f1_c_link_status_du = f1_c_link_status_du
        self.number_of_alarms = number_of_alarms
        self.ip_addresses = ip_addresses
        self.mrbts_id = mrbts_id
        self.nrbts_id = nrbts_id
        self.nr_du_id = nr_du_id
        self.is_vdu_start_up = is_vdu_start_up
        self.additional_info = additional_info

        super(VDUStateData, self).__init__()
